head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vRowCount = 0;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.processGp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        $c.bns.BnsPanelToGroupBox(panel_Top);
        $c.bns.BnsPanelToGroupBox(panel_1);
        $c.bns.BnsPanelToGroupBox(panel_2);
        // 데이터셋 초기화
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_List_2",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        $c.bns.fn_SetBnsCombo("ULDBNS21100.xml", dts_Cntrcd, '01371'); // 국가 01371
        // 공통콤보
        const arrCid = [];
        // arrCid.push({cid:'02025', cnm:'cmb_cnrt_cd'});//국가
        arrCid.push({
            cid: '03473',
            cnm: 'cmb_inst_stat_cd'
        }); // 기관상태
        $c.bns.fn_SetBnsComboToCode("ULDBNS21100.xml", dts_Temp, arrCid);

        // 버튼 세팅
        btn_reset.setDisabled(false);
        btn_reset.setBackgroundImage("../img/bns/btn_new_n.gif");
        btn_insert.setDisabled(true);
        btn_insert.setBackgroundImage("../img/bns/btn_40_d.gif");
        btn_update.setDisabled(true);
        btn_update.setBackgroundImage("../img/bns/btn_modify_nd.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
