/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        /**********************************************
         * 함수명   : txb_ISUR_CD > onblur
         * 설명      : 발행기관 코드 변경
         ***********************************************/
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21100.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name btn_reset_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_reset_onclick = function() {
    try {
        /**********************************************
         * Event   : btn_reset > OnClick
         * 설명    : 초기버튼 클릭
         ***********************************************/
        dts_List_2.removeAll();
        dts_List_2.insertRow();
        edt_inst_cd.setDisabled(false);
        cmb_cnrt_cd.indes = 0;
        cmb_inst_stat_cd.setSelectedIndex(0);
        btn_reset.setDisabled(true);
        btn_reset.setBackgroundImage("../img/bns/btn_new_nd.gif");
        btn_insert.setDisabled(false);
        btn_insert.setBackgroundImage("../img/bns/btn_40.gif");
        btn_update.setDisabled(true);
        btn_update.setBackgroundImage("../img/bns/btn_modify_nd.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21100.btn_reset_onclick" });
    }
};

/**
 * @method
 * @name btn_insert_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_insert_onclick = async function() {
    try {
        /**********************************************
         * Event   : btn_insert > OnClick
         * 설명    : 신규버튼 클릭
         ***********************************************/
        scwin.processGp = SCREN_PROCS_TP_CD_02;
        if (edt_inst_cd.getValue() === "") {
            await $c.win.alert("기관코드를 입력하세요");
            return false;
        }

        // 자리수 체크
        if (!$c.stf.checkMaxLength(txb_inst_nm, 25, '한글기관명')) return false;
        if (!$c.stf.checkMaxLength(txb_inst_srt_nm, 20, '한글기관약명')) return false;
        const pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
        let str = txb_inst_eng_nm.getValue();
        for (let i = 0; i < str.length; i++) {
            if (pattern.test(str.substring(i, i + 1))) {
                await $c.win.alert('영문기관명에 한글은 사용할 수 없습니다');
                txb_inst_eng_nm.focus();
                return false;
            }
        }
        let str = txb_inst_eng_srt_nm.getValue();
        for (let i = 0; i < str.length; i++) {
            if (pattern.test(str.substring(i, i + 1))) {
                await $c.win.alert('영문기관약명에 한글은 사용할 수 없습니다');
                txb_inst_eng_srt_nm.focus();
                return false;
            }
        }

        // 자리수 체크
        if (!$c.stf.checkMaxLength(txb_addr, 200, '주소')) return false;
        if (!$c.stf.checkMaxLength(txb_dong_addr, 200, '동이하주소')) return false;
        if (!$c.stf.checkMaxLength(txb_inst_kind_contn, 20, '기관종류')) return false;
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21100.btn_insert_onclick" });
    }
};

/**
 * @method
 * @name btn_update_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_update_onclick = function() {
    try {
        /**********************************************
