         ***********************************************/
        scwin.processGp = SCREN_PROCS_TP_CD_03;
        scwin.update();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21100.btn_update_onclick" });
    }
};

/**
 * @method
