        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21100.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        /**********************************************
         * Event   : dts_List_1 > OnLoadCompleted
         * 설명    : dts_List_1 조회성공시 처리
         ***********************************************/
        scwin.vRowCount = rowcount;
        if (rowcount > 0) {
            btn_reset.setDisabled(false);
            btn_reset.setBackgroundImage("../img/bns/btn_new_n.gif");
            btn_insert.setDisabled(true);
            btn_insert.setBackgroundImage("../img/bns/btn_40d.gif");
            btn_update.setDisabled(false);
            btn_update.setBackgroundImage("../img/bns/btn_modify_n.gif");
        } else {
            btn_reset.setDisabled(false);
            btn_reset.setBackgroundImage("../img/bns/btn_new_n.gif");
            btn_insert.setDisabled(true);
            btn_insert.setBackgroundImage("../img/bns/btn_40_d.gif");
            btn_update.setDisabled(true);
            btn_update.setBackgroundImage("../img/bns/btn_modify_nd.gif");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21100.dts_List_1_OnLoadCompleted" });
    }
};

