     ***********************************************/
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnFail = async function() {
    try {
        /**********************************************
         * Event   : trs_save > OnFail
         * 설명    : 저장 에러시 처리
         ***********************************************/
        if (scwin.processGp === SCREN_PROCS_TP_CD_02) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "신규등록"));
        }
        if (scwin.processGp === SCREN_PROCS_TP_CD_03) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        }
        if (scwin.processGp === SCREN_PROCS_TP_CD_04) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21100.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        /**********************************************
         * Event   : trs_save > OnSuccess
         * 설명    : 저장 성공시 처리
         ***********************************************/
        // 버튼 세팅
        btn_reset.setDisabled(true);
        btn_reset.setBackgroundImage("../img/bns/btn_new_nd.gif");
        btn_insert.setDisabled(true);
        btn_insert.setBackgroundImage("../img/bns/btn_40_d.gif");
        btn_update.setDisabled(false);
        btn_update.setBackgroundImage("../img/bns/btn_modify_n.gif");

        // 메세지처리
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        // 조회
        await scwin.listSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21100.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_List_1_OnRowPosChanged
 * @description List 1 On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnRowPosChanged = async function(row) {
    try {
        /**********************************************
         * Event   : dts_List_1 > OnRowPosChanged
         * 설명    : 그리드 위치 변경시 세팅
         ***********************************************/
        await scwin.searchDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21100.dts_List_1_OnRowPosChanged" });
    }
};

