         * Event   : btn_zip_search > onclick
         * 설명    : 우편번호 검색
         ***********************************************/
        fn_SetPar = scwin.setZipCode;
        $c.lc.fn_PopFindZipCd();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21100.btn_zip_search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSearch
 * @description 보증기관관리 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSearch = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_LIST";
    url += "&queryId=lds.stf.bnsinst.select.list";
    url += "&SCREN_ID=" + "ULDBNS21100.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_COM_NM=" + txb_com_abbrv.getValue(); //
    url += "&{P}V_INST_STAT_CD=" + cmb_sch_inst_stat_cd.getValue(); //

    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return url;
};

/**
 * @method
 * @name searchDetail
 * @description 보증기관관리 상세조회
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function(row) {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_LISTDETAIL";
    url += "&queryId=lds.stf.bnsinst.select.listdetail";
    url += "&SCREN_ID=" + "ULDBNS21100.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_CD=" + dts_List_1.getCellData(row, "BND_INST_CD"); //

    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    btn_reset.setDisabled(false);
    btn_reset.setBackgroundImage("../img/bns/btn_new_n.gif");
    btn_insert.setDisabled(true);
    btn_insert.setBackgroundImage("../img/bns/btn_40_d.gif");
    btn_update.setDisabled(false);
    btn_update.setBackgroundImage("../img/bns/btn_modify_n.gif");
    return url;
};

/**
 * @method
 * @name chkInstCd
 * @description 보증기관관리 코드존재여부 체크
 * @param {String} vsInstCd vsInstCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkInstCd = async function(vsInstCd) {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_LISTDETAIL";
    url += "&queryId=lds.stf.bnsinst.select.listdetail";
    url += "&SCREN_ID=" + "ULDBNS21100.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_CD=" + edt_inst_cd.getValue(); //

    const sbmOptions = {
        id : "sbm_dts_ChkCd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ChkCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_ChkCd.getCellData(0, "BND_INST_CD") === null) {
        return false;
    } else {
        return true;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name insert
 * @description 보증기관등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "신규등록"))) return;
    if (await scwin.chkInstCd()) {
        await $c.win.alert("[" + dts_ChkCd.getCellData(0, "BND_INST_CD") + "]기관코드는 [" + dts_ChkCd.getCellData(0, "INST_NM") + "]에서 사용중입니다.");
        return;
    }
    dts_List_2.setCellData(1, "ZIP_CD", dts_List_2.getCellData(1, "ZIP_CD").replace("-", ""));
    let url = "/bns/Inst.do?method=insertInst";
    url += "&SCREN_ID=" + "ULDBNS21100.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_save.Action = $c.lc.fn_encodeNSession(url);
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List_2)";
    trs_save.Post();
};

/**
 * @method
 * @name update
 * @description 보증기관 수정
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수정"))) return;
    dts_List_2.setCellData(1, "ZIP_CD", dts_List_2.getCellData(1, "ZIP_CD").replace("-", ""));
    let url = "/bns/Inst.do?method=updateInst";
    url += "&SCREN_ID=" + "ULDBNS21100.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_save.Action = $c.lc.fn_encodeNSession(url);
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List_2)";
    trs_save.Post();
};

/**
 * @method
 * @name getParInst
 * @description 기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: txb_isur_cd.getValue(),
        INST_NM: txb_com_abbrv.getValue(),
        LBL_NM: '',
        INIT_TP_CD: "2"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParInst
 * @description 기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParInst = function(arrPar) {
    if (typeof(arrPar[0].INST_CD) !== 'undefined') {
        txb_isur_cd.setValue(arrPar[0].INST_CD);
        txb_com_abbrv.setValue(arrPar[0].INST_NM);
    }
};

/**
 * @method
 * @name setZipCode
 * @description 우편번호
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function(arrPar) {
    edt_zip_cd.setValue(arrPar[0]);
    txb_addr.setValue(arrPar[1]);
};
